//! error.db schema + migrations (#2260) — run by {@link crate::Store::open}. One SQLite db per
//! project hub: `projects/<key>/error.db`. Three tables: `faults` (one row per fingerprint,
//! Sentry-style, carrying the occurrence count), `events` (individual occurrences, capped per
//! fingerprint), and `runs` (what each wrapped command COST — see below).
//!
//! # Why `runs` lives here and not in a store of its own
//!
//! `bsc errors run` is already the one wrapper around every build and launch, it already holds this
//! db's handle, and the worker protocol already tells a worker to use it. Recording cost anywhere else
//! would mean a SECOND wrapper around the same command — two call sites to keep in step, and a worker
//! having to remember which one answers which question. So this db is the project's RUN store, not
//! only its fault store: a run's outcome and a run's cost are the same event seen twice.
//!
//! `runs` records a CLEAN run as well as a failed one, which `faults` deliberately does not. A trend
//! needs the green runs — a store holding only the failures cannot answer "is the build getting
//! slower", which is the whole question `bsc mem build` exists for.

use rusqlite::Connection;

/// Every table, in the order `clear()` truncates them — the child (`events`) before the parent so the
/// reset is order-safe, and the single source of truth for the store's table set.
pub(crate) const ALL_TABLES: &[&str] = &["events", "faults", "runs"];

pub(crate) fn migrate(conn: &Connection) -> rusqlite::Result<()> {
    conn.execute_batch(
        "PRAGMA journal_mode = WAL;
         CREATE TABLE IF NOT EXISTS faults (
            fingerprint  TEXT PRIMARY KEY,
            stage        TEXT NOT NULL DEFAULT 'runtime',
            level        TEXT NOT NULL DEFAULT 'error',
            title        TEXT NOT NULL,
            sample_stack TEXT,
            source_hint  TEXT,
            release      TEXT,
            count        INTEGER NOT NULL DEFAULT 0,
            first_seen   INTEGER NOT NULL DEFAULT 0,
            last_seen    INTEGER NOT NULL DEFAULT 0,
            resolved_at  INTEGER
         );
         CREATE TABLE IF NOT EXISTS events (
            id           INTEGER PRIMARY KEY AUTOINCREMENT,
            fingerprint  TEXT NOT NULL,
            ts           INTEGER NOT NULL DEFAULT 0,
            context      TEXT
         );
         CREATE TABLE IF NOT EXISTS runs (
            id             INTEGER PRIMARY KEY AUTOINCREMENT,
            ts             INTEGER NOT NULL DEFAULT 0,
            stage          TEXT NOT NULL DEFAULT 'build',
            source         TEXT NOT NULL DEFAULT '',
            cmd            TEXT NOT NULL DEFAULT '',
            ok             INTEGER NOT NULL DEFAULT 0,
            exit_code      INTEGER NOT NULL DEFAULT 0,
            -- Wall clock, and the PEAK of the summed RSS of the child's whole process tree. Both are
            -- nullable because a measurement that could not be taken must read as absent rather than
            -- as zero: a build recorded at 0 ms would poison every median it entered.
            ms             INTEGER,
            peak_rss_bytes INTEGER
         );
         CREATE INDEX IF NOT EXISTS idx_events_fp   ON events(fingerprint, id);
         CREATE INDEX IF NOT EXISTS idx_faults_seen ON faults(last_seen);
         CREATE INDEX IF NOT EXISTS idx_runs_ts     ON runs(ts);",
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn migrate_is_idempotent() {
        let conn = Connection::open_in_memory().unwrap();
        migrate(&conn).unwrap();
        migrate(&conn).unwrap(); // re-running on an existing db is a no-op
        let n: i64 = conn
            .query_row("SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ('faults','events','runs')", [], |r| r.get(0))
            .unwrap();
        assert_eq!(n, 3);
    }

    /// `runs` must be reachable on a db created BEFORE it existed — the migration is `IF NOT EXISTS`
    /// over a live store, not a fresh-schema-only path. Every hub on disk already has an error.db.
    #[test]
    fn runs_is_added_to_a_db_that_predates_it() {
        let conn = Connection::open_in_memory().unwrap();
        // The old two-table schema, as a pre-`runs` hub carries it.
        conn.execute_batch(
            "CREATE TABLE faults (fingerprint TEXT PRIMARY KEY, stage TEXT, level TEXT, title TEXT,
                 sample_stack TEXT, source_hint TEXT, release TEXT, count INTEGER, first_seen INTEGER,
                 last_seen INTEGER, resolved_at INTEGER);
             CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, fingerprint TEXT NOT NULL,
                 ts INTEGER, context TEXT);",
        )
        .unwrap();
        migrate(&conn).unwrap();
        conn.execute("INSERT INTO runs (ts, ms) VALUES (1, 2)", []).unwrap();
    }

    /// `clear()` truncates every table it knows about, and a table missing from [`ALL_TABLES`] would be
    /// silently left behind — so the list is pinned against the schema rather than trusted.
    #[test]
    fn all_tables_names_every_table_the_schema_creates() {
        let conn = Connection::open_in_memory().unwrap();
        migrate(&conn).unwrap();
        let mut stmt = conn
            .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")
            .unwrap();
        let mut found: Vec<String> =
            stmt.query_map([], |r| r.get::<_, String>(0)).unwrap().map(Result::unwrap).collect();
        found.sort();
        let mut known: Vec<String> = ALL_TABLES.iter().map(|s| s.to_string()).collect();
        known.sort();
        assert_eq!(found, known, "ALL_TABLES has drifted from the schema");
    }
}

